BOOK.add({
  subject: "reas",
  id: "reas-05",
  title: "रक्त संबंध",
  notes: "\n    <h3>रक्त संबंध (Blood Relation) क्या है?</h3>\n    <p>इन प्रश्नों में परिवार के सदस्यों के बीच कुछ संबंध दिए जाते हैं और किन्हीं दो व्यक्तियों का आपसी संबंध पूछा जाता है। सफलता के तीन आधार हैं — (1) हिन्दी के संबंध-सूचक शब्दों का सही ज्ञान, (2) <b>पारिवारिक वृक्ष (Family Tree)</b> बनाना, और (3) लिंग (पुरुष/स्त्री) तथा पीढ़ी का ध्यान रखना।</p>\n    <div class=\"tip\">कभी भी केवल दिमाग़ में हल न करें — हर प्रश्न में छोटा-सा पारिवारिक वृक्ष खींचें। संकेत: पुरुष = (+) या □, स्त्री = (−) या ○, पति-पत्नी = दोहरी रेखा (=), भाई-बहन = क्षैतिज रेखा (—), माता-पिता से संतान = ऊर्ध्वाधर रेखा (|)।</div>\n\n    <h3>1. पितृ पक्ष (पिता की ओर के संबंध)</h3>\n    <table>\n      <tr><th>संबंध</th><th>नाम</th></tr>\n      <tr><td>पिता के पिता / माता</td><td>दादा / दादी</td></tr>\n      <tr><td>पिता के बड़े भाई / उनकी पत्नी</td><td>ताऊ / ताई</td></tr>\n      <tr><td>पिता के छोटे भाई / उनकी पत्नी</td><td>चाचा / चाची</td></tr>\n      <tr><td>पिता की बहन / उनका पति</td><td>बुआ / फूफा</td></tr>\n      <tr><td>चाचा-ताऊ के बच्चे</td><td>चचेरे भाई-बहन</td></tr>\n      <tr><td>बुआ के बच्चे</td><td>फुफेरे भाई-बहन</td></tr>\n      <tr><td>पुत्र का पुत्र / पुत्री</td><td>पोता / पोती</td></tr>\n      <tr><td>भाई का पुत्र / पुत्री</td><td>भतीजा / भतीजी</td></tr>\n    </table>\n\n    <h3>2. मातृ पक्ष (माता की ओर के संबंध)</h3>\n    <table>\n      <tr><th>संबंध</th><th>नाम</th></tr>\n      <tr><td>माता के पिता / माता</td><td>नाना / नानी</td></tr>\n      <tr><td>माता का भाई / उसकी पत्नी</td><td>मामा / मामी</td></tr>\n      <tr><td>माता की बहन / उसका पति</td><td>मौसी / मौसा</td></tr>\n      <tr><td>मामा के बच्चे</td><td>ममेरे भाई-बहन</td></tr>\n      <tr><td>मौसी के बच्चे</td><td>मौसेरे भाई-बहन</td></tr>\n      <tr><td>पुत्री का पुत्र / पुत्री</td><td>नाती (दौहित्र) / नातिन</td></tr>\n      <tr><td>बहन का पुत्र / पुत्री</td><td>भांजा / भांजी</td></tr>\n    </table>\n\n    <h3>3. विवाह से बने संबंध (ससुराल पक्ष)</h3>\n    <table>\n      <tr><th>संबंध</th><th>नाम</th></tr>\n      <tr><td>पति/पत्नी के पिता / माता</td><td>ससुर / सास</td></tr>\n      <tr><td>पुत्र की पत्नी</td><td>पुत्रवधू (बहू)</td></tr>\n      <tr><td>पुत्री का पति</td><td>दामाद (जामाता)</td></tr>\n      <tr><td>भाई की पत्नी</td><td>भाभी (भौजाई)</td></tr>\n      <tr><td>बहन का पति</td><td>बहनोई (जीजा)</td></tr>\n      <tr><td>पत्नी का भाई / उसकी पत्नी</td><td>साला / सलहज</td></tr>\n      <tr><td>पत्नी की बहन / उसका पति</td><td>साली / साढ़ू</td></tr>\n      <tr><td>पति का बड़ा भाई / उसकी पत्नी</td><td>जेठ / जेठानी</td></tr>\n      <tr><td>पति का छोटा भाई / उसकी पत्नी</td><td>देवर / देवरानी</td></tr>\n      <tr><td>पति की बहन / उसका पति</td><td>ननद / ननदोई</td></tr>\n      <tr><td>पुत्र या पुत्री के सास-ससुर</td><td>समधी / समधिन</td></tr>\n    </table>\n\n    <h3>4. प्रश्नों के प्रकार</h3>\n    <h4>(क) प्रत्यक्ष कथन वाले प्रश्न</h4>\n    <p>\"A, B का भाई है। B, C की बहन है। C, D का पिता है। A, D का कौन है?\" — वृक्ष: A, B, C एक ही पीढ़ी के भाई-बहन; C (पुरुष) का संतान D। अतः A, D के पिता का भाई = <b>चाचा</b>।</p>\n    <h4>(ख) इशारा करके बताने वाले (Pointing) प्रश्न</h4>\n    <p>इनमें वाक्य को <b>अंत से शुरू करके</b> पीछे की ओर खोलें और \"मेरा/मेरी\" को वक्ता से बदलें।</p>\n    <p><b>उदाहरण:</b> राम ने कहा, \"वह मेरे पिता के इकलौते पुत्र का पुत्र है।\" — \"मेरे पिता का इकलौता पुत्र\" = स्वयं राम; \"राम का पुत्र\" ⇒ वह व्यक्ति राम का <b>पुत्र</b> है।</p>\n    <p><b>उदाहरण:</b> रीना ने कहा, \"वह मेरी माँ के पिता का इकलौता पुत्र है।\" — माँ के पिता = नाना; नाना का इकलौता पुत्र = <b>मामा</b>।</p>\n    <h4>(ग) कूटबद्ध संबंध (Coded Relations)</h4>\n    <p>जैसे A + B = \"A, B की माता\", A − B = \"A, B का भाई\", A × B = \"A, B का पिता\", A ÷ B = \"A, B की बहन\"। व्यंजक को <b>बाएँ से दाएँ</b> एक-एक संकेत खोलें।</p>\n    <p><b>उदाहरण:</b> P − Q × R: P, Q का भाई; Q, R का पिता ⇒ P, R के पिता का भाई = <b>चाचा</b>।</p>\n    <p><b>उदाहरण:</b> P ÷ Q + R: P, Q की बहन; Q, R की माता ⇒ P, R की माँ की बहन = <b>मौसी</b>।</p>\n    <h4>(घ) पारिवारिक पहेली (Puzzle)</h4>\n    <p>पाँच-छह सदस्यों के बारे में कई कथन होते हैं। पहले निश्चित जानकारी (पति-पत्नी, माता-पिता) से वृक्ष बनाएँ, फिर अधूरी जानकारी जोड़ें।</p>\n\n    <h3>5. महत्त्वपूर्ण सावधानियाँ</h3>\n    <ul>\n      <li><b>लिंग कल्पित न करें:</b> \"A, B का पुत्र है\" से केवल A पुरुष है; B पिता है या माता — यह पता नहीं। \"B, C की बहन है\" से B स्त्री है।</li>\n      <li><b>\"इकलौता पुत्र\" और वक्ता:</b> यदि वक्ता पुरुष है तो \"मेरे पिता का इकलौता पुत्र\" = वह स्वयं। \"मेरी माँ की इकलौती पुत्री\" — वक्ता स्त्री हो तो वह स्वयं।</li>\n      <li><b>\"पुत्र नहीं है\" वाला जाल:</b> \"A, B का पिता है पर B, A का पुत्र नहीं\" ⇒ B पुत्री है।</li>\n      <li><b>पीढ़ी गिनें:</b> दादा/नाना = +2 पीढ़ी, पिता/चाचा/मामा = +1, भाई/चचेरा भाई = 0, पुत्र/भतीजा/भांजा = −1, पोता/नाती = −2।</li>\n      <li><b>ताऊ बनाम चाचा:</b> आयु न दी हो तो परीक्षा में \"चाचा\" को पिता के भाई का सामान्य उत्तर माना जाता है।</li>\n    </ul>\n\n    <h3>6. हल करने का चरणबद्ध तरीका</h3>\n    <ol>\n      <li>कथनों में से हर व्यक्ति का लिंग जहाँ निश्चित हो, लिख लें।</li>\n      <li>पति-पत्नी के जोड़े को एक पंक्ति में (=) लिखें।</li>\n      <li>बच्चों को उनके नीचे, भाई-बहनों को एक ही क्षैतिज पंक्ति में रखें।</li>\n      <li>पूछे गए दो व्यक्तियों के बीच का मार्ग वृक्ष पर खोजें और उसे एक संबंध-शब्द में बदलें।</li>\n      <li>पुष्टि करें — \"प्रश्न में किसका किससे\" संबंध पूछा है (A का B से या B का A से)। दिशा उलटने पर उत्तर बदल जाता है (मामा ↔ भांजा)।</li>\n    </ol>\n\n    <h3>7. और हल किए उदाहरण</h3>\n    <p><b>(क)</b> \"Q, R की पत्नी है। R, S का पुत्र है। S, T का पति है। Q का T से संबंध?\" — वृक्ष: S (पुरुष) = T (स्त्री); उनके नीचे R (पुरुष) = Q। अतः Q, T के पुत्र की पत्नी ⇒ <b>पुत्रवधू</b>।</p>\n    <p><b>(ख)</b> \"एक पुरुष की ओर इशारा करते हुए गीता ने कहा, 'उसका पुत्र मेरे पति का इकलौता पुत्र है।'\" — गीता के पति का इकलौता पुत्र = गीता का पुत्र; वही उस पुरुष का पुत्र है, अतः वह पुरुष गीता का <b>पति</b> है।</p>\n    <p><b>(ग) कूट:</b> P # Q $ R % S जहाँ # = \"की पुत्री\", $ = \"का पति\", % = \"की बहन\"। P, Q की पुत्री; Q, R का पति ⇒ R, P की माँ; R, S की बहन ⇒ S, P का मामा या मौसी (S का लिंग अज्ञात), पर P, S की <b>भांजी</b> निश्चित है। यहीं \"किसका किससे\" का महत्त्व दिखता है — उलटी दिशा का उत्तर अनिश्चित है, सीधी दिशा का निश्चित।</p>\n    <div class=\"tip\">यदि कोई प्रश्न किसी व्यक्ति के लिंग पर निर्भर हो और लिंग दिया न हो, तो विकल्पों में \"निर्धारित नहीं किया जा सकता\" सही उत्तर हो सकता है — पर पहले जाँच लें कि दूसरी दिशा से उत्तर निश्चित तो नहीं।</div>\n  ",
  extra: "\n    <h3>गहन तथ्य / ट्रिक्स</h3>\n    <ul>\n      <li><b>दिशा का जाल:</b> \"A, B का मामा है\" तो \"B, A का भांजा/भांजी\" है; \"A, B का चाचा\" तो \"B, A का भतीजा/भतीजी\"। प्रश्न में क्रम ध्यान से पढ़ें।</li>\n      <li><b>भतीजा बनाम भांजा:</b> भाई की संतान — भतीजा/भतीजी; बहन की संतान — भांजा/भांजी। यह नियम पुरुष और स्त्री दोनों के लिए समान है (बुआ के लिए भी भाई का बेटा भतीजा ही है)।</li>\n      <li><b>पोता बनाम नाती:</b> पुत्र की संतान — पोता/पोती; पुत्री की संतान — नाती/नातिन। यह भी दादा-दादी और नाना-नानी दोनों पर लागू होता है।</li>\n      <li><b>\"दो माताएँ, दो पुत्रियाँ\":</b> न्यूनतम 3 सदस्य (नानी, माँ, पुत्री) — बीच वाली महिला माता भी है और पुत्री भी।</li>\n      <li><b>कूट-संबंध में दादा बनाम नाना:</b> M × P × N (पिता का पिता) = दादा; M × P + N (माता का पिता) = नाना। \"दादा\" पूछे तो बीच वाला व्यक्ति पुरुष (पिता) होना चाहिए।</li>\n      <li><b>चचेरा / ममेरा / फुफेरा / मौसेरा:</b> संबंध उस व्यक्ति की दृष्टि से नाम पाता है जिसका संबंध पूछा गया है। A मामा का बेटा है, तो A उस बच्चे के लिए ममेरा भाई है; उलटी दिशा में वह बच्चा A के लिए फुफेरा भाई है।</li>\n      <li><b>पीढ़ी-अंतर ट्रिक:</b> उत्तर विकल्पों में पीढ़ी देखें — यदि आपका मार्ग एक पीढ़ी ऊपर जाता है तो \"पोता/भतीजा\" जैसे विकल्प तुरंत हटाएँ।</li>\n      <li><b>समधी-समधिन:</b> दो परिवार जिनके बच्चों का आपस में विवाह हुआ — वे एक-दूसरे के समधी/समधिन।</li>\n      <li><b>साढ़ू:</b> दो बहनों के पति आपस में साढ़ू कहलाते हैं; दो भाइयों की पत्नियाँ आपस में देवरानी-जेठानी।</li>\n      <li><b>\"इकलौता\" शब्द की शक्ति:</b> \"मेरे दादा का इकलौता पुत्र\" = मेरे पिता (क्योंकि पिता दादा के पुत्र हैं ही); इसके बिना वह चाचा भी हो सकता था।</li>\n      <li><b>न्यूनतम सदस्य वाले प्रश्न:</b> एक व्यक्ति कई भूमिकाएँ निभा सकता है (माता + पुत्री, पिता + पुत्र)। \"दो पिता और दो पुत्र\" = दादा, पिता, पुत्र = 3 व्यक्ति।</li>\n      <li><b>ससुराल-शब्दों का युग्म:</b> सास-ससुर ↔ बहू/दामाद; जेठ/देवर ↔ भाभी (भाई की पत्नी के लिए); ननद ↔ भाभी; साला/साली ↔ जीजा।</li>\n      <li><b>सौतेले संबंध</b> परीक्षा में तब तक न मानें जब तक प्रश्न में स्पष्ट न लिखा हो; पति-पत्नी के बच्चे दोनों के बच्चे माने जाते हैं।</li>\n    </ul>\n  ",
  questions: [
    {"q":"A, B का भाई है। B, C की बहन है। C, D का पिता है। A का D से क्या संबंध है?","o":["पिता","भाई","चाचा","मामा"],"a":2,"e":"<b>हल:</b><br>चरण 1: A, B का भाई है → A पुरुष है; A और B भाई-बहन (एक ही पीढ़ी)।<br>चरण 2: B, C की बहन है → A, B, C तीनों भाई-बहन हैं।<br>चरण 3: C, D का पिता है → C पुरुष, D अगली पीढ़ी में।<br>वंश-वृक्ष:<br>A — B — C (भाई-बहन)<br>↓<br>D<br>चरण 4: A = D के पिता (C) का भाई = चाचा।<br>अतः उत्तर = <b>चाचा</b><br><b>ध्यान दें:</b> मामा माँ का भाई होता है; यहाँ A, D के पिता का भाई है।"},
    {"q":"एक व्यक्ति की ओर इशारा करते हुए राम ने कहा, \"वह मेरे पिता के इकलौते पुत्र का पुत्र है।\" वह व्यक्ति राम का कौन है?","o":["पुत्र","भाई","भतीजा","पिता"],"a":0,"e":"<b>हल:</b><br>चरण 1: राम के पिता का इकलौता पुत्र = स्वयं राम (राम भी अपने पिता का पुत्र है और पुत्र केवल एक है)।<br>चरण 2: उस पुत्र (राम) का पुत्र = राम का पुत्र (राम से एक पीढ़ी नीचे)।<br>अतः उत्तर = <b>पुत्र</b><br><b>ध्यान दें:</b> \"पिता का पुत्र\" देखकर भाई चुनना सामान्य गलती है — \"इकलौता\" शब्द बताता है कि वह स्वयं राम है।"},
    {"q":"एक लड़के की फ़ोटो की ओर इशारा करते हुए एक महिला ने कहा, \"इसकी माँ मेरी माँ की इकलौती पुत्री है।\" लड़का उस महिला का कौन है?","o":["भाई","भतीजा","भांजा","पुत्र"],"a":3,"e":"<b>हल:</b><br>चरण 1: महिला की माँ की इकलौती पुत्री = स्वयं वह महिला (महिला भी अपनी माँ की पुत्री है)।<br>चरण 2: लड़के की माँ = वही महिला।<br>चरण 3: अतः लड़का महिला से एक पीढ़ी नीचे — उसका पुत्र।<br>अतः उत्तर = <b>पुत्र</b><br><b>ध्यान दें:</b> भांजा तब होता जब लड़के की माँ महिला की बहन होती; पर \"इकलौती पुत्री\" होने से कोई बहन नहीं है।"},
    {"q":"एक पुरुष का परिचय कराते हुए रीना ने कहा, \"वह मेरी माँ के पिता का इकलौता पुत्र है।\" वह पुरुष रीना का कौन है?","o":["चाचा","मामा","नाना","भाई"],"a":1,"e":"<b>हल:</b><br>चरण 1: रीना की माँ के पिता = रीना के नाना (दो पीढ़ी ऊपर)।<br>चरण 2: नाना का इकलौता पुत्र = रीना की माँ का भाई (एक पीढ़ी ऊपर, माँ की ओर से)।<br>चरण 3: माँ का भाई = मामा।<br>अतः उत्तर = <b>मामा</b><br><b>ध्यान दें:</b> चाचा पिता का भाई होता है; यहाँ संबंध माँ की ओर से है।"},
    {"q":"P की पत्नी Q है। Q, R की माँ है। S, R की बहन है। S का P से क्या संबंध है?","o":["बहन","पुत्री","पत्नी","भतीजी"],"a":1,"e":"<b>हल:</b><br>चरण 1: Q, P की पत्नी है → P पुरुष, Q स्त्री; दोनों पति-पत्नी।<br>चरण 2: Q, R की माँ है → P, R का पिता है।<br>चरण 3: S, R की बहन है → S भी P-Q की संतान और स्त्री है।<br>वंश-वृक्ष:<br>P (पुरुष) = Q (स्त्री)<br>↓<br>R — S (स्त्री)<br>अतः S, P की = <b>पुत्री</b>"},
    {"q":"A, B की माँ है। C, A का पिता है। D, C का पुत्र है। D का B से क्या संबंध है?","o":["चाचा","भाई","नाना","मामा"],"a":3,"e":"<b>हल:</b><br>चरण 1: A, B की माँ है → A स्त्री, B उससे एक पीढ़ी नीचे।<br>चरण 2: C, A का पिता है → C, B का नाना।<br>चरण 3: D, C का पुत्र है → D, A का भाई (A की पीढ़ी में, पुरुष)।<br>वंश-वृक्ष:<br>C (पुरुष)<br>↓<br>A (स्त्री) — D (पुरुष)<br>↓<br>B<br>चरण 4: D = B की माँ का भाई = मामा।<br>अतः उत्तर = <b>मामा</b><br><b>ध्यान दें:</b> \"नाना\" C है, D नहीं; और D, B के पिता का नहीं, माँ का भाई है, इसलिए चाचा नहीं।"},
    {"q":"X, Y का भाई है। Z, Y का पिता है। W, Z की माँ है। X का W से क्या संबंध है?","o":["पोता","पुत्र","नाती","भतीजा"],"a":0,"e":"<b>हल:</b><br>चरण 1: X, Y का भाई है → X पुरुष; X, Y एक ही पीढ़ी।<br>चरण 2: Z, Y का पिता है → Z, X का भी पिता।<br>चरण 3: W, Z की माँ है → W, X की पिता की माँ = दादी।<br>वंश-वृक्ष:<br>W (स्त्री)<br>↓<br>Z (पुरुष)<br>↓<br>X (पुरुष) — Y<br>चरण 4: X, W के पुत्र (Z) का पुत्र है = पोता।<br>अतः उत्तर = <b>पोता</b><br><b>ध्यान दें:</b> नाती = पुत्री का पुत्र; यहाँ बीच की कड़ी Z पुत्र है, इसलिए पोता।"},
    {"q":"रमेश ने एक महिला की ओर इशारा करते हुए कहा, \"यह मेरी बहन के इकलौते भाई की पत्नी है।\" महिला रमेश की कौन है?","o":["बहन","भाभी","पत्नी","बेटी"],"a":2,"e":"<b>हल:</b><br>चरण 1: रमेश की बहन का इकलौता भाई = स्वयं रमेश (रमेश भी उस बहन का भाई है और भाई केवल एक है)।<br>चरण 2: उस भाई (रमेश) की पत्नी = रमेश की पत्नी।<br>अतः उत्तर = <b>पत्नी</b><br><b>ध्यान दें:</b> भाभी तभी होती जब रमेश का कोई दूसरा भाई होता; \"इकलौते\" शब्द से यह संभव नहीं।"},
    {"q":"A की पुत्री B है। B का पुत्र C है। C का A से क्या संबंध है?","o":["पोता","भतीजा","पुत्र","नाती"],"a":3,"e":"<b>हल:</b><br>चरण 1: B, A की पुत्री है → B, A से एक पीढ़ी नीचे (पुत्री की ओर)।<br>चरण 2: C, B का पुत्र है → C, A से दो पीढ़ी नीचे।<br>चरण 3: पुत्री का पुत्र = नाती; (पुत्र का पुत्र = पोता)।<br>अतः उत्तर = <b>नाती</b>"},
    {"q":"अमित की बुआ के पति अमित के क्या लगते हैं?","o":["मौसा","मामा","फूफा","चाचा"],"a":2,"e":"<b>हल:</b><br>चरण 1: अमित की बुआ = अमित के पिता की बहन।<br>चरण 2: बुआ का पति = फूफा।<br>अतः उत्तर = <b>फूफा</b><br><b>याद रखें:</b> मौसी का पति = मौसा, मामा की पत्नी = मामी, चाचा की पत्नी = चाची।"},
    {"q":"माँ की बहन का पति क्या कहलाता है?","o":["फूफा","मौसा","मामा","ताऊ"],"a":1,"e":"<b>हल:</b><br>चरण 1: माँ की बहन = मौसी।<br>चरण 2: मौसी का पति = मौसा।<br>अतः उत्तर = <b>मौसा</b><br><b>ध्यान दें:</b> फूफा = पिता की बहन (बुआ) का पति।"},
    {"q":"किसी पुरुष की पत्नी का भाई उसका क्या कहलाता है?","o":["साला","जीजा","देवर","बहनोई"],"a":0,"e":"<b>हल:</b><br>चरण 1: पुरुष की पत्नी का भाई = साला।<br>चरण 2: (उलटा संबंध — पत्नी के भाई के लिए वह पुरुष = जीजा/बहनोई।)<br>अतः उत्तर = <b>साला</b><br><b>ध्यान दें:</b> देवर = पति का छोटा भाई (स्त्री की ओर से)।"},
    {"q":"किसी स्त्री के पति का छोटा भाई उसका क्या कहलाता है?","o":["देवर","जेठ","साला","ननदोई"],"a":0,"e":"<b>हल:</b><br>चरण 1: स्त्री के पति का छोटा भाई = देवर।<br>चरण 2: पति का बड़ा भाई = जेठ।<br>अतः उत्तर = <b>देवर</b><br><b>ध्यान दें:</b> साला = पत्नी का भाई (पुरुष की ओर से); ननदोई = पति की बहन का पति।"},
    {"q":"बहन का पति क्या कहलाता है?","o":["साला","बहनोई","देवर","जेठ"],"a":1,"e":"<b>हल:</b><br>चरण 1: बहन का पति = बहनोई (जीजा)।<br>चरण 2: उलटा — बहनोई के लिए आप उसकी पत्नी के भाई = साला।<br>अतः उत्तर = <b>बहनोई</b>"},
    {"q":"पिता के पिता की पत्नी क्या कहलाती है?","o":["नानी","माँ","दादी","बुआ"],"a":2,"e":"<b>हल:</b><br>चरण 1: पिता के पिता = दादा।<br>चरण 2: दादा की पत्नी = दादी।<br>अतः उत्तर = <b>दादी</b><br><b>ध्यान दें:</b> नानी = माँ की माँ।"},
    {"q":"भाई की पत्नी क्या कहलाती है?","o":["ननद","साली","देवरानी","भाभी"],"a":3,"e":"<b>हल:</b><br>चरण 1: भाई की पत्नी = भाभी।<br>चरण 2: उलटा — भाभी के लिए पति की बहन = ननद।<br>अतः उत्तर = <b>भाभी</b><br><b>ध्यान दें:</b> देवरानी = देवर की पत्नी; साली = पत्नी की बहन।"},
    {"q":"एक परिवार में A (पुरुष) और B पति-पत्नी हैं। C और D उनके पुत्र तथा F उनकी पुत्री है। E, C की पत्नी है। E का A से क्या संबंध है?","o":["पुत्री","पत्नी","पुत्रवधू","बहन"],"a":2,"e":"<b>हल:</b><br>चरण 1: A (पुरुष) = B (पत्नी); इनकी संतानें C, D (पुत्र), F (पुत्री)।<br>चरण 2: E, C की पत्नी है → E, A के पुत्र की पत्नी।<br>वंश-वृक्ष:<br>A (पुरुष) = B<br>↓<br>C = E, D, F<br>चरण 3: पुत्र की पत्नी = पुत्रवधू (बहू)।<br>अतः उत्तर = <b>पुत्रवधू</b>"},
    {"q":"एक परिवार में A (पुरुष) और B पति-पत्नी हैं। C और D उनके पुत्र तथा F उनकी पुत्री है। E, C की पत्नी है। E का F से क्या संबंध है?","o":["भाभी","ननद","बहन","सास"],"a":0,"e":"<b>हल:</b><br>चरण 1: A = B; संतानें C (पुत्र), D (पुत्र), F (पुत्री)।<br>चरण 2: E, C की पत्नी है।<br>चरण 3: F, C की बहन है → E, F के भाई की पत्नी।<br>चरण 4: भाई की पत्नी = भाभी।<br>अतः उत्तर = <b>भाभी</b><br><b>ध्यान दें:</b> ननद उलटा संबंध है — F, E की ननद है।"},
    {"q":"यदि A + B का अर्थ \"A, B की माता है\", A − B का \"A, B का भाई है\", A × B का \"A, B का पिता है\" और A ÷ B का \"A, B की बहन है\", तो P × Q − R में P का R से क्या संबंध है?","o":["चाचा","भाई","दादा","पिता"],"a":3,"e":"<b>हल:</b><br>चरण 1: P × Q → P, Q का पिता (P पुरुष)।<br>चरण 2: Q − R → Q, R का भाई → Q और R भाई-बहन।<br>चरण 3: P, Q का पिता है, अतः R का भी पिता।<br>वंश-वृक्ष: P → (Q — R)<br>अतः उत्तर = <b>पिता</b>"},
    {"q":"यदि A + B का अर्थ \"A, B की माता है\", A − B का \"A, B का भाई है\", A × B का \"A, B का पिता है\" और A ÷ B का \"A, B की बहन है\", तो P + Q ÷ R में P का R से क्या संबंध है?","o":["बहन","माता","मौसी","दादी"],"a":1,"e":"<b>हल:</b><br>चरण 1: P + Q → P, Q की माता (P स्त्री)।<br>चरण 2: Q ÷ R → Q, R की बहन → Q और R भाई-बहन।<br>चरण 3: P, Q की माता है, अतः R की भी माता।<br>अतः उत्तर = <b>माता</b>"},
    {"q":"यदि A + B का अर्थ \"A, B की माता है\", A − B का \"A, B का भाई है\", A × B का \"A, B का पिता है\" और A ÷ B का \"A, B की बहन है\", तो P − Q × R में P का R से क्या संबंध है?","o":["मामा","चाचा","पिता","भाई"],"a":1,"e":"<b>हल:</b><br>चरण 1: P − Q → P, Q का भाई (P पुरुष, Q की पीढ़ी में)।<br>चरण 2: Q × R → Q, R का पिता (Q पुरुष)।<br>चरण 3: P = R के पिता (Q) का भाई = चाचा।<br>वंश-वृक्ष:<br>P — Q (भाई)<br>↓<br>R<br>अतः उत्तर = <b>चाचा</b><br><b>ध्यान दें:</b> मामा तब होता जब Q, R की माता होती (+ चिह्न)।"},
    {"q":"यदि A + B का अर्थ \"A, B की माता है\", A − B का \"A, B का भाई है\", A × B का \"A, B का पिता है\" और A ÷ B का \"A, B की बहन है\", तो P ÷ Q + R में P का R से क्या संबंध है?","o":["बुआ","माता","नानी","मौसी"],"a":3,"e":"<b>हल:</b><br>चरण 1: P ÷ Q → P, Q की बहन (P स्त्री)।<br>चरण 2: Q + R → Q, R की माता (Q स्त्री)।<br>चरण 3: P = R की माता (Q) की बहन = मौसी।<br>अतः उत्तर = <b>मौसी</b><br><b>ध्यान दें:</b> बुआ = पिता की बहन; यहाँ Q माता है, पिता नहीं।"},
    {"q":"यदि A + B का अर्थ \"A, B की माता है\", A − B का \"A, B का भाई है\" और A × B का \"A, B का पिता है\", तो किस व्यंजक का अर्थ है कि M, N का दादा है?","o":["M × P × N","M × P + N","M − P × N","M + P × N"],"a":0,"e":"<b>हल:</b><br>लक्ष्य: M, N का दादा = M, N के <b>पिता</b> का पिता।<br>चरण 1: (A) M × P × N → M, P का पिता; P, N का पिता → M = N के पिता का पिता = दादा ✓<br>चरण 2: (B) M × P + N → P, N की माता → M = नाना ✗<br>चरण 3: (C) M − P × N → M, P का भाई; P, N का पिता → M = चाचा ✗<br>चरण 4: (D) M + P × N → M, P की माता → M = दादी (स्त्री) ✗<br>अतः उत्तर = <b>M × P × N</b>"},
    {"q":"राम के पिता के इकलौते भाई की इकलौती पुत्री राम की क्या लगेगी?","o":["बहन","भतीजी","चचेरी बहन","बुआ"],"a":2,"e":"<b>हल:</b><br>चरण 1: राम के पिता का इकलौता भाई = राम के चाचा/ताऊ (एक पीढ़ी ऊपर)।<br>चरण 2: चाचा की इकलौती पुत्री = राम की पीढ़ी की, पर सगी नहीं।<br>चरण 3: चाचा की पुत्री = चचेरी बहन।<br>अतः उत्तर = <b>चचेरी बहन</b><br><b>ध्यान दें:</b> सगी बहन तब होती जब वह राम के पिता की ही पुत्री होती।"},
    {"q":"एक महिला की ओर इशारा करते हुए अजय ने कहा, \"उसकी माँ की इकलौती बेटी मेरी पत्नी है।\" वह महिला अजय की कौन है?","o":["साली","बहन","सास","पत्नी"],"a":3,"e":"<b>हल:</b><br>चरण 1: उस महिला की माँ की इकलौती बेटी = स्वयं वह महिला (वह भी अपनी माँ की बेटी है)।<br>चरण 2: वह इकलौती बेटी = अजय की पत्नी।<br>चरण 3: अतः वह महिला ही अजय की पत्नी है।<br>अतः उत्तर = <b>पत्नी</b><br><b>ध्यान दें:</b> साली चुनना गलत है — \"इकलौती\" होने से महिला की कोई बहन नहीं है।"},
    {"q":"एक लड़की की ओर इशारा करते हुए सुरेश ने कहा, \"यह मेरे दादा के इकलौते पुत्र की पुत्री है।\" लड़की सुरेश की कौन है?","o":["चचेरी बहन","भतीजी","बहन","पुत्री"],"a":2,"e":"<b>हल:</b><br>चरण 1: सुरेश के दादा का इकलौता पुत्र = सुरेश के पिता (सुरेश के पिता भी दादा के पुत्र हैं और पुत्र केवल एक है)।<br>चरण 2: पिता की पुत्री = सुरेश की बहन (सुरेश की पीढ़ी)।<br>अतः उत्तर = <b>बहन</b><br><b>ध्यान दें:</b> चचेरी बहन तब होती जब दादा का कोई दूसरा पुत्र (चाचा) होता।"},
    {"q":"एक पुरुष की ओर इशारा करते हुए गीता ने कहा, \"उसका पुत्र मेरे पति का इकलौता पुत्र है।\" वह पुरुष गीता का कौन है?","o":["ससुर","पति","पिता","भाई"],"a":1,"e":"<b>हल:</b><br>चरण 1: गीता के पति का इकलौता पुत्र = गीता के पति का पुत्र (गीता का पुत्र)।<br>चरण 2: उस पुरुष का पुत्र = वही लड़का।<br>चरण 3: लड़के का पिता = गीता का पति; अतः वह पुरुष = गीता का पति।<br>अतः उत्तर = <b>पति</b><br><b>ध्यान दें:</b> ससुर तब होता जब उस पुरुष का पुत्र गीता का पति होता।"},
    {"q":"A, B का पिता है लेकिन B, A का पुत्र नहीं है। B, A का कौन है?","o":["पुत्री","पुत्र","भतीजी","पत्नी"],"a":0,"e":"<b>हल:</b><br>चरण 1: A, B का पिता है → B, A की संतान (एक पीढ़ी नीचे)।<br>चरण 2: B, A का पुत्र नहीं है → B स्त्री है।<br>चरण 3: स्त्री संतान = पुत्री।<br>अतः उत्तर = <b>पुत्री</b>"},
    {"q":"मीना, राजू की बहन है। राजू, गोपाल का पुत्र है। गोपाल, किशन का इकलौता पुत्र है। मीना का किशन से क्या संबंध है?","o":["पोती","पुत्री","नातिन","बहू"],"a":0,"e":"<b>हल:</b><br>चरण 1: गोपाल, किशन का इकलौता पुत्र है → किशन सबसे ऊपर की पीढ़ी।<br>चरण 2: राजू, गोपाल का पुत्र है और मीना, राजू की बहन है → मीना भी गोपाल की पुत्री।<br>वंश-वृक्ष:<br>किशन<br>↓<br>गोपाल (पुत्र)<br>↓<br>राजू — मीना<br>चरण 3: मीना = किशन के पुत्र की पुत्री = पोती।<br>अतः उत्तर = <b>पोती</b><br><b>ध्यान दें:</b> नातिन = पुत्री की पुत्री; यहाँ बीच की कड़ी पुत्र (गोपाल) है।"},
    {"q":"Q, R की पत्नी है। R, S का पुत्र है। S, T का पति है। Q का T से क्या संबंध है?","o":["पुत्री","पुत्रवधू","बहन","सास"],"a":1,"e":"<b>हल:</b><br>चरण 1: S, T का पति है → S पुरुष, T स्त्री (पति-पत्नी)।<br>चरण 2: R, S का पुत्र है → R, T का भी पुत्र।<br>चरण 3: Q, R की पत्नी है → Q, T के पुत्र की पत्नी।<br>वंश-वृक्ष:<br>S = T<br>↓<br>R = Q<br>अतः Q, T की = <b>पुत्रवधू</b>"},
    {"q":"A की माँ B है। B की बहन C है। C का पति D है। D का A से क्या संबंध है?","o":["फूफा","मामा","मौसा","चाचा"],"a":2,"e":"<b>हल:</b><br>चरण 1: B, A की माँ है।<br>चरण 2: C, B की बहन है → C = A की मौसी।<br>चरण 3: D, C का पति है → मौसी का पति = मौसा।<br>अतः उत्तर = <b>मौसा</b><br><b>ध्यान दें:</b> फूफा = बुआ (पिता की बहन) का पति।"},
    {"q":"राहुल की माँ, कविता की बहन है। कविता, राहुल की कौन है?","o":["बुआ","मामी","चाची","मौसी"],"a":3,"e":"<b>हल:</b><br>चरण 1: राहुल की माँ और कविता बहनें हैं।<br>चरण 2: कविता = राहुल की माँ की बहन।<br>चरण 3: माँ की बहन = मौसी।<br>अतः उत्तर = <b>मौसी</b>"},
    {"q":"एक व्यक्ति ने एक फ़ोटो दिखाकर कहा, \"मेरा कोई भाई या बहन नहीं है, पर इस व्यक्ति का पिता मेरे पिता का पुत्र है।\" फ़ोटो किसकी है?","o":["उसके भाई की","उसके भतीजे की","उसके पुत्र की","स्वयं उसकी"],"a":2,"e":"<b>हल:</b><br>चरण 1: \"मेरे पिता का पुत्र\" — व्यक्ति का कोई भाई-बहन नहीं, अतः पिता का पुत्र = स्वयं वह व्यक्ति।<br>चरण 2: फ़ोटो वाले का पिता = वह व्यक्ति स्वयं।<br>चरण 3: अतः फ़ोटो वाला उसकी अगली पीढ़ी — उसका पुत्र।<br>अतः उत्तर = <b>उसके पुत्र की</b><br><b>ध्यान दें:</b> \"स्वयं उसकी\" गलत है — फ़ोटो वाले का पिता वह है, फ़ोटो वाला स्वयं नहीं।"},
    {"q":"A के 3 पुत्र हैं और प्रत्येक पुत्र के 2-2 बच्चे हैं। A के कुल कितने पोते-पोतियाँ हैं?","o":["6","5","8","9"],"a":0,"e":"<b>हल:</b><br>चरण 1: A के 3 पुत्र हैं।<br>चरण 2: प्रत्येक पुत्र के 2 बच्चे → कुल बच्चे = 3 × 2 = 6।<br>चरण 3: पुत्रों के बच्चे = A के पोते-पोतियाँ।<br>अतः उत्तर = <b>6</b>"},
    {"q":"दो माताएँ और दो पुत्रियाँ एक साथ बाज़ार गईं। कम से कम कितनी महिलाएँ गईं?","o":["4","2","5","3"],"a":3,"e":"<b>हल:</b><br>चरण 1: न्यूनतम संख्या के लिए तीन पीढ़ियाँ लें — नानी, माँ, बेटी।<br>चरण 2: माताएँ = नानी (माँ की माँ) और माँ (बेटी की माँ) → 2 माताएँ।<br>चरण 3: पुत्रियाँ = माँ (नानी की पुत्री) और बेटी → 2 पुत्रियाँ।<br>चरण 4: माँ दोनों गिनती में आती है → कुल 3 महिलाएँ।<br>अतः उत्तर = <b>3</b>"},
    {"q":"एक परिवार में दादा, दादी, उनके 2 पुत्र, दोनों पुत्रों की पत्नियाँ और प्रत्येक पुत्र के 2-2 बच्चे हैं। परिवार में कुल कितने सदस्य हैं?","o":["8","10","12","9"],"a":1,"e":"<b>हल:</b><br>चरण 1: पहली पीढ़ी — दादा + दादी = 2<br>चरण 2: दूसरी पीढ़ी — 2 पुत्र + उनकी 2 पत्नियाँ = 4<br>चरण 3: तीसरी पीढ़ी — प्रत्येक पुत्र के 2 बच्चे → 2 × 2 = 4<br>चरण 4: कुल = 2 + 4 + 4 = 10<br>अतः उत्तर = <b>10</b><br><b>ध्यान दें:</b> पुत्रों की पत्नियाँ गिनना न भूलें (भूलने पर 8 आता है)।"},
    {"q":"मेरे पिता के छोटे भाई की पत्नी मेरी क्या लगेगी?","o":["मौसी","चाची","मामी","बुआ"],"a":1,"e":"<b>हल:</b><br>चरण 1: मेरे पिता का छोटा भाई = चाचा (पिता की पीढ़ी)।<br>चरण 2: चाचा की पत्नी = चाची।<br>अतः उत्तर = <b>चाची</b><br><b>ध्यान दें:</b> पिता के बड़े भाई की पत्नी = ताई; माँ के भाई की पत्नी = मामी।"},
    {"q":"रवि की माँ के भाई की पत्नी रवि की क्या लगेगी?","o":["चाची","मौसी","ताई","मामी"],"a":3,"e":"<b>हल:</b><br>चरण 1: रवि की माँ का भाई = मामा।<br>चरण 2: मामा की पत्नी = मामी।<br>अतः उत्तर = <b>मामी</b>"},
    {"q":"किसी व्यक्ति की पुत्रवधू (बहू) की माँ उसकी क्या कहलाती है?","o":["समधिन","सास","ननद","देवरानी"],"a":0,"e":"<b>हल:</b><br>चरण 1: व्यक्ति की पुत्रवधू = उसके पुत्र की पत्नी।<br>चरण 2: पुत्रवधू की माँ और उस व्यक्ति के बच्चे आपस में विवाहित हैं — दोनों परिवारों के माता-पिता एक-दूसरे के समधी/समधिन होते हैं।<br>चरण 3: स्त्री होने से = समधिन।<br>अतः उत्तर = <b>समधिन</b><br><b>ध्यान दें:</b> सास वह है जो पति/पत्नी की माँ हो; पुत्रवधू की माँ व्यक्ति की सास नहीं।"},
    {"q":"P, Q की बहन है। Q, R का भाई है। R, S की माँ है। इनमें से निश्चित रूप से पुरुष कौन है?","o":["P","R","Q","S"],"a":2,"e":"<b>हल:</b><br>चरण 1: P, Q की बहन है → P स्त्री।<br>चरण 2: Q, R का भाई है → Q पुरुष (निश्चित)।<br>चरण 3: R, S की माँ है → R स्त्री।<br>चरण 4: S के लिंग का कोई संकेत नहीं।<br>अतः निश्चित रूप से पुरुष = <b>Q</b>"},
    {"q":"A, B का भाई है। C, B का पिता है। D, C का भाई है। E, D की पुत्री है। A का E से क्या संबंध है?","o":["भाई","चाचा","भतीजा","चचेरा भाई"],"a":3,"e":"<b>हल:</b><br>चरण 1: A, B का भाई है और C, B का पिता है → C, A का भी पिता।<br>चरण 2: D, C का भाई है → D, A के चाचा/ताऊ।<br>चरण 3: E, D की पुत्री है → E, A की पीढ़ी में (चचेरी बहन)।<br>वंश-वृक्ष:<br>पीढ़ी 1: C — D (भाई)<br>पीढ़ी 2: C की संतान A, B | D की संतान E<br>चरण 4: A (पुरुष) = E के पिता (D) के भाई (C) का पुत्र = चचेरा भाई।<br>अतः उत्तर = <b>चचेरा भाई</b><br><b>ध्यान दें:</b> सगा भाई नहीं, क्योंकि A और E के पिता अलग हैं।"},
    {"q":"राम, श्याम का पिता है। श्याम की बहन गीता है। गीता का पुत्र मोहन है। राम का मोहन से क्या संबंध है?","o":["दादा","मामा","नाना","पिता"],"a":2,"e":"<b>हल:</b><br>चरण 1: राम, श्याम का पिता है; गीता, श्याम की बहन है → राम, गीता का भी पिता।<br>चरण 2: मोहन, गीता का पुत्र है → मोहन, राम से दो पीढ़ी नीचे।<br>वंश-वृक्ष:<br>राम<br>↓<br>श्याम — गीता<br>↓<br>मोहन (गीता का पुत्र)<br>चरण 3: राम = मोहन की माँ (गीता) का पिता = नाना।<br>अतः उत्तर = <b>नाना</b><br><b>ध्यान दें:</b> मामा श्याम है, राम नहीं; दादा तब होता जब मोहन, श्याम का पुत्र होता।"},
    {"q":"किसी स्त्री की पुत्री के पुत्र का पिता उस स्त्री का क्या लगेगा?","o":["पुत्र","दामाद","पति","भाई"],"a":1,"e":"<b>हल:</b><br>चरण 1: स्त्री की पुत्री (एक पीढ़ी नीचे)।<br>चरण 2: पुत्री का पुत्र = स्त्री का नाती (दो पीढ़ी नीचे)।<br>चरण 3: नाती का पिता = पुत्री का पति (एक पीढ़ी नीचे)।<br>चरण 4: पुत्री का पति = दामाद।<br>अतः उत्तर = <b>दामाद</b>"},
    {"q":"अमर ने कहा, \"रानी मेरे पिता के इकलौते पुत्र के पुत्र की पत्नी है।\" रानी, अमर की कौन है?","o":["पुत्रवधू","पत्नी","पुत्री","भाभी"],"a":0,"e":"<b>हल:</b><br>चरण 1: अमर के पिता का इकलौता पुत्र = स्वयं अमर।<br>चरण 2: उस पुत्र (अमर) का पुत्र = अमर का पुत्र (एक पीढ़ी नीचे)।<br>चरण 3: रानी = अमर के पुत्र की पत्नी = पुत्रवधू।<br>अतः उत्तर = <b>पुत्रवधू</b><br><b>ध्यान दें:</b> भाभी तब होती जब अमर का कोई भाई होता; \"इकलौते पुत्र\" से यह संभव नहीं।"},
    {"q":"A, B का पुत्र है और B पुरुष है। C, B की इकलौती बहन है। D, C का पुत्र है। A का D से क्या संबंध है?","o":["ममेरा भाई","फुफेरा भाई","चचेरा भाई","सगा भाई"],"a":0,"e":"<b>हल:</b><br>चरण 1: B पुरुष है और A, B का पुत्र है।<br>चरण 2: C, B की इकलौती बहन है → C, A की बुआ।<br>चरण 3: D, C का पुत्र है → D, A की पीढ़ी में।<br>वंश-वृक्ष:<br>पीढ़ी 1: B (पुरुष) — C (बहन)<br>पीढ़ी 2: B का पुत्र A | C का पुत्र D<br>चरण 4: D की दृष्टि से A = माँ (C) के भाई (B) का पुत्र = ममेरा भाई।<br>अतः A, D का = <b>ममेरा भाई</b><br><b>ध्यान दें:</b> उलटा पढ़ने पर D, A का फुफेरा भाई है — प्रश्न \"A का D से\" पूछ रहा है, इसलिए D की दृष्टि से A का संबंध देखें।"},
    {"q":"किसी पुरुष के पुत्र की पत्नी का ससुर कौन है?","o":["उसका भाई","वह पुरुष स्वयं","उसका पिता","उसका पुत्र"],"a":1,"e":"<b>हल:</b><br>चरण 1: पुरुष का पुत्र (एक पीढ़ी नीचे)।<br>चरण 2: पुत्र की पत्नी = पुरुष की पुत्रवधू।<br>चरण 3: पुत्रवधू का ससुर = उसके पति का पिता = वही पुरुष।<br>अतः उत्तर = <b>वह पुरुष स्वयं</b>"},
    {"q":"A का भाई B है। B का पुत्र C है। C की बहन D है। D की माँ E है। E का A से क्या संबंध है?","o":["बहन","माँ","भाभी","पत्नी"],"a":2,"e":"<b>हल:</b><br>चरण 1: B, A का भाई है (A की पीढ़ी)।<br>चरण 2: C, B का पुत्र है; D, C की बहन है → D भी B की संतान।<br>चरण 3: E, D की माँ है → E, B की पत्नी (B, D का पिता है)।<br>वंश-वृक्ष:<br>A — B = E<br>↓<br>C — D<br>चरण 4: E = A के भाई की पत्नी = भाभी।<br>अतः उत्तर = <b>भाभी</b>"},
    {"q":"यदि A # B का अर्थ \"A, B की पुत्री है\", A $ B का \"A, B का पति है\" और A % B का \"A, B की बहन है\", तो P # Q $ R % S में P का S से क्या संबंध है?","o":["भतीजी","पुत्री","बहन","भांजी"],"a":3,"e":"<b>हल:</b><br>चरण 1: P # Q → P, Q की पुत्री (P स्त्री)।<br>चरण 2: Q $ R → Q, R का पति → R, P की माँ।<br>चरण 3: R % S → R, S की बहन → S, P की माँ का भाई या बहन (मामा/मौसी)।<br>वंश-वृक्ष:<br>Q = R — S<br>↓<br>P (पुत्री)<br>चरण 4: P = S की बहन (R) की पुत्री = भांजी।<br>अतः उत्तर = <b>भांजी</b><br><b>ध्यान दें:</b> भतीजी तब होती जब P, S के भाई की पुत्री होती; यहाँ P की माँ R, S की बहन है।"},
    {"q":"Q, P की माँ है। R, Q का भाई है। S, R का पिता है। S का P से क्या संबंध है?","o":["दादा","मामा","नाना","पिता"],"a":2,"e":"<b>हल:</b><br>चरण 1: Q, P की माँ है।<br>चरण 2: R, Q का भाई है → R, P का मामा।<br>चरण 3: S, R का पिता है → S, Q का भी पिता।<br>वंश-वृक्ष:<br>S<br>↓<br>Q — R<br>↓<br>P<br>चरण 4: S = P की माँ का पिता = नाना।<br>अतः उत्तर = <b>नाना</b>"},
    {"q":"राधा की सास के इकलौते पुत्र की बहन राधा की क्या लगती है?","o":["ननद","भाभी","देवरानी","जेठानी"],"a":0,"e":"<b>हल:</b><br>चरण 1: राधा की सास = राधा के पति की माँ।<br>चरण 2: सास का इकलौता पुत्र = राधा का पति।<br>चरण 3: पति की बहन = ननद।<br>अतः उत्तर = <b>ननद</b>"},
    {"q":"विमल की पत्नी की बहन विमल की क्या लगती है?","o":["सलहज","ननद","भाभी","साली"],"a":3,"e":"<b>हल:</b><br>चरण 1: विमल की पत्नी की बहन = साली।<br>चरण 2: (पत्नी का भाई = साला; साले की पत्नी = सलहज।)<br>अतः उत्तर = <b>साली</b><br><b>ध्यान दें:</b> ननद = पति की बहन (स्त्री की ओर से)।"},
    {"q":"किसी स्त्री के पति की बहन का पति उसका क्या कहलाता है?","o":["बहनोई","ननदोई","साढ़ू","देवर"],"a":1,"e":"<b>हल:</b><br>चरण 1: स्त्री के पति की बहन = ननद।<br>चरण 2: ननद का पति = ननदोई।<br>अतः उत्तर = <b>ननदोई</b><br><b>ध्यान दें:</b> साढ़ू = पत्नी की बहन का पति (पुरुष की ओर से); बहनोई = अपनी बहन का पति।"},
    {"q":"किसी पुरुष की पत्नी की बहन का पति उसका क्या कहलाता है?","o":["साला","साढ़ू","ननदोई","बहनोई"],"a":1,"e":"<b>हल:</b><br>चरण 1: पुरुष की पत्नी की बहन = साली।<br>चरण 2: साली का पति = साढ़ू।<br>अतः उत्तर = <b>साढ़ू</b>"},
    {"q":"मोहन की बहन का पुत्र मोहन का क्या लगेगा?","o":["भतीजा","पोता","नाती","भांजा"],"a":3,"e":"<b>हल:</b><br>चरण 1: मोहन की बहन (मोहन की पीढ़ी)।<br>चरण 2: बहन का पुत्र (एक पीढ़ी नीचे) = भांजा।<br>अतः उत्तर = <b>भांजा</b><br><b>ध्यान दें:</b> भाई का पुत्र = भतीजा।"},
    {"q":"सीमा के भाई का पुत्र सीमा का क्या लगेगा?","o":["भतीजा","भांजा","पोता","देवर"],"a":0,"e":"<b>हल:</b><br>चरण 1: सीमा का भाई (सीमा की पीढ़ी)।<br>चरण 2: भाई का पुत्र (एक पीढ़ी नीचे) = भतीजा।<br>अतः उत्तर = <b>भतीजा</b><br><b>ध्यान दें:</b> बहन का पुत्र भांजा होता है।"},
    {"q":"पिता की बहन क्या कहलाती है?","o":["मामी","चाची","बुआ","मौसी"],"a":2,"e":"<b>हल:</b><br>चरण 1: पिता की बहन = बुआ।<br>चरण 2: (माँ की बहन = मौसी, चाचा की पत्नी = चाची।)<br>अतः उत्तर = <b>बुआ</b>"},
    {"q":"माँ के पिता को क्या कहते हैं?","o":["दादा","मामा","ताऊ","नाना"],"a":3,"e":"<b>हल:</b><br>चरण 1: माँ के पिता = नाना।<br>चरण 2: (पिता के पिता = दादा।)<br>अतः उत्तर = <b>नाना</b>"},
    {"q":"पिता के बड़े भाई को क्या कहा जाता है?","o":["मामा","चाचा","ताऊ","फूफा"],"a":2,"e":"<b>हल:</b><br>चरण 1: पिता का बड़ा भाई = ताऊ (ताया)।<br>चरण 2: पिता का छोटा भाई = चाचा।<br>अतः उत्तर = <b>ताऊ</b>"},
    {"q":"दो सगे भाइयों की पत्नियाँ आपस में क्या कहलाती हैं?","o":["सास-बहू","देवरानी-जेठानी","समधिन","ननद-भाभी"],"a":1,"e":"<b>हल:</b><br>चरण 1: दो सगे भाई — बड़ा और छोटा।<br>चरण 2: बड़े भाई की पत्नी = जेठानी; छोटे भाई की पत्नी = देवरानी।<br>चरण 3: आपस में = देवरानी-जेठानी।<br>अतः उत्तर = <b>देवरानी-जेठानी</b>"},
    {"q":"पिता की माँ की माँ क्या कहलाती है?","o":["परदादी","परनानी","नानी","दादी"],"a":0,"e":"<b>हल:</b><br>चरण 1: पिता की माँ = दादी।<br>चरण 2: दादी की माँ = परदादी (तीन पीढ़ी ऊपर)।<br>अतः उत्तर = <b>परदादी</b><br><b>ध्यान दें:</b> परनानी = माँ की माँ की माँ (नानी की माँ)।"},
    {"q":"बुआ का पुत्र आपका क्या लगता है?","o":["फुफेरा भाई","चचेरा भाई","मौसेरा भाई","ममेरा भाई"],"a":0,"e":"<b>हल:</b><br>चरण 1: बुआ = पिता की बहन।<br>चरण 2: बुआ का पुत्र = फुफेरा भाई।<br>अतः उत्तर = <b>फुफेरा भाई</b><br><b>याद रखें:</b> चाचा का पुत्र = चचेरा, मामा का = ममेरा, मौसी का = मौसेरा, बुआ का = फुफेरा।"},
    {"q":"किसी स्त्री के पति के पिता उसके क्या लगते हैं?","o":["समधी","जेठ","दादा","ससुर"],"a":3,"e":"<b>हल:</b><br>चरण 1: स्त्री के पति के पिता = ससुर।<br>चरण 2: (पति की माँ = सास।)<br>अतः उत्तर = <b>ससुर</b><br><b>ध्यान दें:</b> जेठ = पति का बड़ा भाई; समधी = पुत्र/पुत्री का ससुर।"},
    {"q":"किसी व्यक्ति की पुत्री की पुत्री उसकी क्या लगती है?","o":["भतीजी","नातिन","पोती","भांजी"],"a":1,"e":"<b>हल:</b><br>चरण 1: व्यक्ति की पुत्री (एक पीढ़ी नीचे)।<br>चरण 2: पुत्री की पुत्री = नातिन (दो पीढ़ी नीचे)।<br>अतः उत्तर = <b>नातिन</b><br><b>ध्यान दें:</b> पुत्र की पुत्री = पोती।"},
    {"q":"मेरे पिता की माँ का पति मेरा कौन है?","o":["पिता","नाना","दादा","चाचा"],"a":2,"e":"<b>हल:</b><br>चरण 1: मेरे पिता की माँ = दादी।<br>चरण 2: दादी का पति = दादा।<br>अतः उत्तर = <b>दादा</b>"},
    {"q":"किसी व्यक्ति की बहन की पुत्री उसकी क्या लगती है?","o":["नातिन","बहू","भतीजी","भांजी"],"a":3,"e":"<b>हल:</b><br>चरण 1: व्यक्ति की बहन (उसी पीढ़ी)।<br>चरण 2: बहन की पुत्री = भांजी।<br>अतः उत्तर = <b>भांजी</b><br><b>ध्यान दें:</b> भाई की पुत्री = भतीजी।"},
    {"q":"एक महिला की ओर इशारा करते हुए विकास ने कहा, \"वह मेरी माँ के इकलौते भाई की इकलौती बहन की पुत्री है।\" वह महिला विकास की कौन है?","o":["ममेरी बहन","मौसेरी बहन","बहन","भांजी"],"a":2,"e":"<b>हल:</b><br>चरण 1: विकास की माँ का इकलौता भाई = विकास का मामा।<br>चरण 2: मामा की इकलौती बहन = विकास की माँ स्वयं (माँ भी मामा की बहन है और बहन केवल एक है)।<br>चरण 3: माँ की पुत्री = विकास की बहन।<br>अतः उत्तर = <b>बहन</b><br><b>ध्यान दें:</b> ममेरी बहन चुनना गलत है — श्रृंखला मामा से लौटकर फिर माँ पर आ जाती है।"},
    {"q":"एक पुरुष की ओर इशारा करते हुए सीमा ने कहा, \"वह मेरे ससुर के इकलौते पुत्र का पुत्र है।\" वह पुरुष सीमा का कौन है?","o":["देवर","पुत्र","भतीजा","पति"],"a":1,"e":"<b>हल:</b><br>चरण 1: सीमा के ससुर = सीमा के पति के पिता।<br>चरण 2: ससुर का इकलौता पुत्र = सीमा का पति।<br>चरण 3: पति का पुत्र = सीमा का पुत्र (एक पीढ़ी नीचे)।<br>अतः उत्तर = <b>पुत्र</b><br><b>ध्यान दें:</b> \"इकलौते पुत्र\" के कारण कोई देवर/जेठ नहीं, अतः भतीजा भी नहीं।"},
    {"q":"राजेश ने एक महिला से कहा, \"तुम्हारी माँ के पति की बहन मेरी मौसी है।\" वह महिला राजेश की कौन है?","o":["ममेरी बहन","फुफेरी बहन","चचेरी बहन","मौसेरी बहन"],"a":0,"e":"<b>हल:</b><br>चरण 1: महिला की माँ का पति = महिला का पिता।<br>चरण 2: पिता की बहन = महिला की बुआ।<br>चरण 3: वही बुआ राजेश की मौसी है → वह राजेश की माँ की बहन है।<br>चरण 4: अतः महिला के पिता, बुआ और राजेश की माँ — तीनों भाई-बहन हैं।<br>वंश-वृक्ष:<br>पीढ़ी 1: महिला के पिता — बुआ/मौसी — राजेश की माँ (तीनों भाई-बहन)<br>पीढ़ी 2: महिला (पिता की संतान) | राजेश (माँ की संतान)<br>चरण 5: महिला = राजेश के मामा (माँ के भाई) की पुत्री = ममेरी बहन।<br>अतः उत्तर = <b>ममेरी बहन</b>"},
    {"q":"अर्जुन की माँ, विक्रम के पिता की इकलौती पुत्री है। विक्रम, अर्जुन का कौन है?","o":["भाई","चाचा","मामा","नाना"],"a":2,"e":"<b>हल:</b><br>चरण 1: विक्रम के पिता की इकलौती पुत्री = विक्रम की बहन (विक्रम पुत्र है)।<br>चरण 2: वही बहन अर्जुन की माँ है।<br>चरण 3: विक्रम = अर्जुन की माँ का भाई = मामा।<br>अतः उत्तर = <b>मामा</b>"},
    {"q":"सरिता ने कहा, \"राजन मेरी नानी के इकलौते दामाद का पुत्र है।\" राजन, सरिता का कौन है?","o":["भांजा","मौसेरा भाई","ममेरा भाई","भाई"],"a":3,"e":"<b>हल:</b><br>चरण 1: सरिता की नानी = सरिता की माँ की माँ।<br>चरण 2: नानी का दामाद = नानी की पुत्री का पति; सरिता की माँ नानी की पुत्री है, अतः सरिता के पिता नानी के दामाद हैं।<br>चरण 3: \"इकलौता दामाद\" → वह सरिता के पिता ही हैं।<br>चरण 4: पिता का पुत्र = सरिता का भाई।<br>अतः उत्तर = <b>भाई</b><br><b>ध्यान दें:</b> मौसेरा भाई तब होता जब नानी का कोई दूसरा दामाद (मौसा) होता।"},
    {"q":"यदि A @ B का अर्थ \"A, B का पुत्र है\", A & B का अर्थ \"A, B की पत्नी है\", A * B का अर्थ \"A, B का पिता है\" और A ! B का अर्थ \"A, B की बहन है\", तो P ! Q * R में P का R से क्या संबंध है?","o":["मौसी","बुआ","चाची","माँ"],"a":1,"e":"<b>हल:</b><br>संकेत: @ = पुत्र, & = पत्नी, * = पिता, ! = बहन।<br>चरण 1: P ! Q → P, Q की बहन (P स्त्री, Q की पीढ़ी)।<br>चरण 2: Q * R → Q, R का पिता (Q पुरुष)।<br>चरण 3: P = R के पिता की बहन = बुआ।<br>अतः उत्तर = <b>बुआ</b><br><b>ध्यान दें:</b> मौसी = माँ की बहन; यहाँ Q पिता है।"},
    {"q":"यदि A @ B का अर्थ \"A, B का पुत्र है\", A & B का अर्थ \"A, B की पत्नी है\", A * B का अर्थ \"A, B का पिता है\" और A ! B का अर्थ \"A, B की बहन है\", तो P @ Q & R * S में P का S से क्या संबंध है?","o":["भाई","पिता","पुत्र","चाचा"],"a":0,"e":"<b>हल:</b><br>संकेत: @ = पुत्र, & = पत्नी, * = पिता, ! = बहन।<br>चरण 1: P @ Q → P, Q का पुत्र।<br>चरण 2: Q & R → Q, R की पत्नी → R, P का पिता।<br>चरण 3: R * S → R, S का पिता → S भी R-Q की संतान।<br>वंश-वृक्ष:<br>R = Q<br>↓<br>P (पुत्र) — S<br>चरण 4: P और S एक ही माता-पिता की संतान, P पुरुष → P, S का भाई।<br>अतः उत्तर = <b>भाई</b>"},
    {"q":"यदि A @ B का अर्थ \"A, B का पुत्र है\", A & B का अर्थ \"A, B की पत्नी है\", A * B का अर्थ \"A, B का पिता है\" और A ! B का अर्थ \"A, B की बहन है\", तो X & Y @ Z में X का Z से क्या संबंध है?","o":["बहन","पुत्री","पत्नी","पुत्रवधू"],"a":3,"e":"<b>हल:</b><br>संकेत: @ = पुत्र, & = पत्नी, * = पिता, ! = बहन।<br>चरण 1: X & Y → X, Y की पत्नी।<br>चरण 2: Y @ Z → Y, Z का पुत्र।<br>चरण 3: X = Z के पुत्र की पत्नी = पुत्रवधू।<br>अतः उत्तर = <b>पुत्रवधू</b>"},
    {"q":"यदि A @ B का अर्थ \"A, B का पुत्र है\", A & B का अर्थ \"A, B की पत्नी है\", A * B का अर्थ \"A, B का पिता है\" और A ! B का अर्थ \"A, B की बहन है\", तो P ! Q * R @ S में P का S से क्या संबंध है?","o":["भाभी","ननद","बहन","सास"],"a":1,"e":"<b>हल:</b><br>संकेत: @ = पुत्र, & = पत्नी, * = पिता, ! = बहन।<br>चरण 1: P ! Q → P, Q की बहन (P स्त्री)।<br>चरण 2: Q * R → Q, R का पिता।<br>चरण 3: R @ S → R, S का पुत्र → S, R का माता या पिता। पिता Q है (और S अलग व्यक्ति है), अतः S = R की माँ = Q की पत्नी।<br>वंश-वृक्ष:<br>P — Q = S<br>↓<br>R<br>चरण 4: P = S के पति (Q) की बहन = ननद।<br>अतः उत्तर = <b>ननद</b><br><b>ध्यान दें:</b> भाभी उलटा संबंध है — S, P की भाभी है।"},
    {"q":"यदि A @ B का अर्थ \"A, B का पुत्र है\", A & B का अर्थ \"A, B की पत्नी है\", A * B का अर्थ \"A, B का पिता है\" और A ! B का अर्थ \"A, B की बहन है\", तो L * M ! N में N का L से क्या संबंध है?","o":["भतीजा","पुत्री","संतान है, पर पुत्र या पुत्री — निश्चित नहीं","पुत्र"],"a":2,"e":"<b>हल:</b><br>संकेत: @ = पुत्र, & = पत्नी, * = पिता, ! = बहन।<br>चरण 1: L * M → L, M का पिता।<br>चरण 2: M ! N → M, N की बहन → N भी L की संतान।<br>चरण 3: N के लिंग का कोई संकेत नहीं (M ! N केवल M का लिंग बताता है)।<br>चरण 4: अतः N, L की संतान है, पर पुत्र है या पुत्री — निश्चित नहीं।<br>अतः उत्तर = <b>संतान है, पर पुत्र या पुत्री — निश्चित नहीं</b>"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए — A, B की माँ है। C, B का भाई है। D, A का पति है।<br>1. D, C का पिता है।<br>2. C, A का पुत्र है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"<b>हल:</b><br>चरण 1: A, B की माँ; C, B का भाई → C भी A की संतान और पुरुष।<br>चरण 2: D, A का पति है → D, B और C दोनों का पिता।<br>वंश-वृक्ष:<br>D = A<br>↓<br>B — C (पुरुष)<br>कथन 1: D, C का पिता — <b>सही</b> (A का पति = C का पिता)।<br>कथन 2: C, A का पुत्र — <b>सही</b> (C पुरुष और A की संतान)।<br>अतः उत्तर = <b>1 और 2 दोनों</b>"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए — P, Q का भाई है। R, Q की बहन है। S, R का पुत्र है।<br>1. P, S का मामा है।<br>2. Q, S का मामा है।<br>निश्चित रूप से सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"<b>हल:</b><br>चरण 1: P, Q का भाई (P पुरुष); R, Q की बहन (R स्त्री) → P, Q, R भाई-बहन।<br>चरण 2: S, R का पुत्र → R, S की माँ।<br>वंश-वृक्ष:<br>P (पु.) — Q (?) — R (स्त्री)<br>↓ (R से)<br>S<br>कथन 1: P = S की माँ का भाई = मामा — <b>निश्चित सही</b>।<br>कथन 2: Q का लिंग अज्ञात — Q मामा या मौसी हो सकता/सकती है — <b>निश्चित नहीं</b>।<br>अतः उत्तर = <b>केवल 1</b>"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए — A के दो बच्चे B और C हैं। D, B की पत्नी है। E, C का पति है।<br>1. B पुरुष है।<br>2. E, D का देवर है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"<b>हल:</b><br>चरण 1: A की दो संतानें B और C।<br>चरण 2: D, B की पत्नी → B पुरुष।<br>चरण 3: E, C का पति → C स्त्री।<br>वंश-वृक्ष:<br>A<br>↓<br>B (पु.) = D ↓&nbsp; C (स्त्री) = E<br>कथन 1: B पुरुष — <b>सही</b>।<br>कथन 2: D के लिए E = पति (B) की बहन (C) का पति = ननदोई, देवर नहीं — <b>गलत</b>।<br>अतः उत्तर = <b>केवल 1</b>"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए — X, Y की पुत्री है। Z, Y का पिता है।<br>1. Z, X का नाना है।<br>2. X, Z की पोती है।<br>निश्चित रूप से सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":3,"e":"<b>हल:</b><br>चरण 1: X, Y की पुत्री; Z, Y का पिता → Z, X के दादा या नाना।<br>चरण 2: Y का लिंग अज्ञात।<br>— यदि Y पुरुष (पिता) → Z = दादा, X = पोती।<br>— यदि Y स्त्री (माँ) → Z = नाना, X = नातिन।<br>कथन 1 (Z नाना) — निश्चित नहीं।<br>कथन 2 (X पोती) — निश्चित नहीं।<br>अतः उत्तर = <b>न तो 1 न ही 2</b>"},
    {"q":"अभिकथन (A): यदि P, Q का भाई है, तो यह निश्चित नहीं कहा जा सकता कि Q, P का भाई है।<br>कारण (R): \"भाई\" शब्द से केवल P का लिंग ज्ञात होता है, Q का नहीं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"<b>हल:</b><br>अभिकथन (A): \"P, Q का भाई है\" से केवल P पुरुष है; Q पुरुष हो तो Q, P का भाई, स्त्री हो तो बहन — अतः निश्चित नहीं → A <b>सही</b>।<br>कारण (R): \"भाई\" शब्द केवल P का लिंग बताता है, Q का नहीं → R <b>सही</b>।<br>R ठीक वही कारण है जिससे A सत्य है → R, A की सही व्याख्या।<br>अतः उत्तर = <b>A और R दोनों सही हैं तथा R, A की सही व्याख्या है</b>"},
    {"q":"अभिकथन (A): चाचा की पुत्री चचेरी बहन कहलाती है।<br>कारण (R): बुआ की पुत्री को फुफेरी बहन कहते हैं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"<b>हल:</b><br>अभिकथन (A): चाचा (पिता का भाई) की पुत्री = चचेरी बहन → <b>सही</b>।<br>कारण (R): बुआ (पिता की बहन) की पुत्री = फुफेरी बहन → <b>सही</b>।<br>R एक अलग संबंध (बुआ) के बारे में है; वह A (चाचा) का कारण नहीं बताता।<br>अतः उत्तर = <b>A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है</b>"},
    {"q":"अभिकथन (A): यदि X, Y की पुत्री है, तो Y, X का पिता या माता है।<br>कारण (R): \"पुत्री\" शब्द से Y का लिंग भी ज्ञात हो जाता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"<b>हल:</b><br>अभिकथन (A): X, Y की पुत्री है → Y, X का माता-पिता (पिता या माता) → <b>सही</b>।<br>कारण (R): \"पुत्री\" शब्द केवल X का लिंग (स्त्री) बताता है; Y पुरुष है या स्त्री, यह ज्ञात नहीं → R <b>गलत</b>।<br>अतः उत्तर = <b>A सही है, R गलत है</b>"},
    {"q":"अभिकथन (A): किसी व्यक्ति की माँ की माँ का पति उसका दादा कहलाता है।<br>कारण (R): पिता के पिता को दादा कहते हैं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":3,"e":"<b>हल:</b><br>अभिकथन (A): माँ की माँ = नानी; नानी का पति = नाना, दादा नहीं → A <b>गलत</b>।<br>कारण (R): पिता के पिता = दादा → R <b>सही</b>।<br>अतः उत्तर = <b>A गलत है, R सही है</b>"},
    {"q":"सूची-I को सूची-II से सुमेलित कीजिए —<br>(A) पति का बड़ा भाई (B) पति के बड़े भाई की पत्नी (C) पत्नी के भाई की पत्नी (D) पुत्र या पुत्री का ससुर<br>1. जेठानी 2. समधी 3. जेठ 4. सलहज","o":["A-4, B-3, C-1, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2"],"a":3,"e":"<b>हल:</b><br>(A) पति का बड़ा भाई = जेठ → 3<br>(B) पति के बड़े भाई (जेठ) की पत्नी = जेठानी → 1<br>(C) पत्नी के भाई (साले) की पत्नी = सलहज → 4<br>(D) पुत्र या पुत्री का ससुर = समधी → 2<br>अतः उत्तर = <b>A-3, B-1, C-4, D-2</b><br><b>शॉर्टकट:</b> A-3 पक्का होते ही विकल्प C और D बचते हैं; C = सलहज (4) से सीधे D मिलता है।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म सही सुमेलित नहीं है?","o":["माँ की माँ — नानी","पति की बहन — साली","पुत्र का पुत्र — पोता","पिता का बड़ा भाई — ताऊ"],"a":1,"e":"<b>हल:</b><br>(A) माँ की माँ = नानी — सही युग्म।<br>(B) पति की बहन = ननद होती है; साली = पत्नी की बहन — <b>गलत युग्म</b>।<br>(C) पुत्र का पुत्र = पोता — सही युग्म।<br>(D) पिता का बड़ा भाई = ताऊ — सही युग्म।<br>अतः उत्तर = <b>पति की बहन — साली</b>"},
    {"q":"छह सदस्यों वाले एक परिवार में A, B, C, D, E और F हैं। B, A का पुत्र है, किंतु A, B की माँ नहीं है। A और C पति-पत्नी हैं। E, C का भाई है। D, A की पुत्री है। F, B का भाई है।<br>इस परिवार में कितने पुरुष सदस्य हैं?","o":["2","3","4","5"],"a":2,"e":"<b>हल:</b><br>चरण 1: B, A का पुत्र है पर A, B की माँ नहीं → A, B का पिता (A पुरुष); B पुरुष।<br>चरण 2: A और C पति-पत्नी → C स्त्री।<br>चरण 3: E, C का भाई → E पुरुष।<br>चरण 4: D, A की पुत्री → D स्त्री।<br>चरण 5: F, B का भाई → F पुरुष।<br>वंश-वृक्ष:<br>A (पु.) = C (स्त्री) — E (पु., C का भाई)<br>↓<br>B (पु.), F (पु.), D (स्त्री)<br>चरण 6: पुरुष = A, B, E, F = 4 (स्त्रियाँ C, D = 2)।<br>अतः उत्तर = <b>4</b>"},
    {"q":"छह सदस्यों वाले एक परिवार में A, B, C, D, E और F हैं। B, A का पुत्र है, किंतु A, B की माँ नहीं है। A और C पति-पत्नी हैं। E, C का भाई है। D, A की पुत्री है। F, B का भाई है।<br>E का D से क्या संबंध है?","o":["मामा","चाचा","नाना","भाई"],"a":0,"e":"<b>हल:</b><br>चरण 1: A (पिता) = C (माँ); इनकी संतानें B, F (पुत्र), D (पुत्री)।<br>चरण 2: E, C का भाई है।<br>वंश-वृक्ष:<br>A = C — E<br>↓<br>B, F, D<br>चरण 3: E = D की माँ (C) का भाई = मामा।<br>अतः उत्तर = <b>मामा</b><br><b>ध्यान दें:</b> चाचा तब होता जब E, पिता A का भाई होता।"},
    {"q":"छह सदस्यों वाले एक परिवार में A, B, C, D, E और F हैं। B, A का पुत्र है, किंतु A, B की माँ नहीं है। A और C पति-पत्नी हैं। E, C का भाई है। D, A की पुत्री है। F, B का भाई है।<br>D का E से क्या संबंध है?","o":["बहन","भांजी","पुत्री","भतीजी"],"a":1,"e":"<b>हल:</b><br>चरण 1: पिछले हल के अनुसार — A (पिता) = C (माँ), संतानें B, F, D (पुत्री); E, C का भाई (D का मामा)।<br>चरण 2: D (स्त्री) = E की बहन (C) की पुत्री।<br>चरण 3: बहन की पुत्री = भांजी।<br>अतः उत्तर = <b>भांजी</b><br><b>ध्यान दें:</b> भतीजी = भाई की पुत्री; यहाँ D, E की बहन की पुत्री है।"},
    {"q":"एक परिवार में तीन पीढ़ियों के छह सदस्य P, Q, R, S, T और U हैं। Q, P की पत्नी है। R और S, P-Q की संतानें हैं। R विवाहित पुरुष है और T उसकी पत्नी है। U, T का इकलौता पुत्र है। S अविवाहित है और U की बुआ है।<br>U का P से क्या संबंध है?","o":["भतीजा","नाती","पोता","पुत्र"],"a":2,"e":"<b>हल:</b><br>चरण 1: P = Q (पति-पत्नी) — पहली पीढ़ी।<br>चरण 2: R (विवाहित पुरुष) और S उनकी संतानें; T, R की पत्नी — दूसरी पीढ़ी।<br>चरण 3: U, T का इकलौता पुत्र → U, R का पुत्र — तीसरी पीढ़ी।<br>वंश-वृक्ष:<br>P = Q<br>↓<br>R (पु.) = T ↓&nbsp; S (स्त्री, अविवाहित)<br>↓<br>U (पुत्र)<br>चरण 4: U = P के पुत्र (R) का पुत्र = पोता।<br>अतः उत्तर = <b>पोता</b>"},
    {"q":"एक परिवार में तीन पीढ़ियों के छह सदस्य P, Q, R, S, T और U हैं। Q, P की पत्नी है। R और S, P-Q की संतानें हैं। R विवाहित पुरुष है और T उसकी पत्नी है। U, T का इकलौता पुत्र है। S अविवाहित है और U की बुआ है।<br>T का S से क्या संबंध है?","o":["भाभी","बहन","देवरानी","ननद"],"a":0,"e":"<b>हल:</b><br>चरण 1: R और S, P-Q की संतानें; S, U की बुआ → S स्त्री, R की बहन।<br>चरण 2: T, R की पत्नी।<br>चरण 3: T = S के भाई (R) की पत्नी = भाभी।<br>अतः उत्तर = <b>भाभी</b><br><b>ध्यान दें:</b> ननद उलटा संबंध है — S, T की ननद है।"},
    {"q":"एक परिवार में तीन पीढ़ियों के छह सदस्य P, Q, R, S, T और U हैं। Q, P की पत्नी है। R और S, P-Q की संतानें हैं। R विवाहित पुरुष है और T उसकी पत्नी है। U, T का इकलौता पुत्र है। S अविवाहित है और U की बुआ है।<br>इस परिवार में कितनी स्त्रियाँ हैं?","o":["1","2","4","3"],"a":3,"e":"<b>हल:</b><br>चरण 1: P — पुरुष (Q उसकी पत्नी है)।<br>चरण 2: Q — स्त्री (पत्नी)।<br>चरण 3: R — पुरुष (कथन में दिया)।<br>चरण 4: T — स्त्री (R की पत्नी)।<br>चरण 5: U — पुरुष (पुत्र)।<br>चरण 6: S — स्त्री (U की बुआ)।<br>स्त्रियाँ = Q, T, S = 3<br>अतः उत्तर = <b>3</b>"},
    {"q":"A, B का पति है। C, A की माँ है। D, C का पति है। E, D की पुत्री है। E का B से क्या संबंध है?","o":["भाभी","ननद","साली","सास"],"a":1,"e":"<b>हल:</b><br>चरण 1: A, B का पति → B स्त्री, A पुरुष।<br>चरण 2: C, A की माँ; D, C का पति → D, A का पिता।<br>चरण 3: E, D की पुत्री → E, A की बहन।<br>वंश-वृक्ष:<br>D = C<br>↓<br>A (पु.) = B ↓&nbsp; E (स्त्री)<br>चरण 4: E = B के पति (A) की बहन = ननद।<br>अतः उत्तर = <b>ननद</b><br><b>ध्यान दें:</b> साली = पत्नी की बहन; यहाँ E, पति की बहन है।"},
    {"q":"J, K का भाई है। K, L की पुत्री है। L, N की पत्नी है। M, L का पिता है। J का M से क्या संबंध है?","o":["पोता","नाती","पुत्र","भांजा"],"a":1,"e":"<b>हल:</b><br>चरण 1: L, N की पत्नी → L स्त्री।<br>चरण 2: K, L की पुत्री; J, K का भाई → J भी L का पुत्र।<br>चरण 3: M, L का पिता।<br>वंश-वृक्ष:<br>M<br>↓<br>L (स्त्री) = N<br>↓<br>J (पु.) — K<br>चरण 4: J = M की पुत्री (L) का पुत्र = नाती।<br>अतः उत्तर = <b>नाती</b><br><b>ध्यान दें:</b> पोता तब होता जब बीच की कड़ी पुत्र होती; यहाँ L पुत्री है।"},
    {"q":"P की माँ और Q दो बहनें हैं। R, Q का इकलौता पुत्र है। R का P से क्या संबंध है?","o":["मौसेरा भाई","ममेरा भाई","फुफेरा भाई","चचेरा भाई"],"a":0,"e":"<b>हल:</b><br>चरण 1: P की माँ और Q बहनें हैं → Q, P की मौसी।<br>चरण 2: R, Q का इकलौता पुत्र → R, P की पीढ़ी में।<br>वंश-वृक्ष:<br>पीढ़ी 1: P की माँ — Q (बहनें)<br>पीढ़ी 2: P (माँ की संतान) | R (Q का पुत्र)<br>चरण 3: R = P की मौसी का पुत्र = मौसेरा भाई।<br>अतः उत्तर = <b>मौसेरा भाई</b>"},
    {"q":"विनोद की पत्नी, सुमन के ससुर की इकलौती पुत्री है। सुमन, विनोद की कौन है?","o":["भाभी","साली","ननद","सलहज"],"a":3,"e":"<b>हल:</b><br>चरण 1: सुमन के ससुर = सुमन के पति के पिता।<br>चरण 2: ससुर की इकलौती पुत्री = सुमन के पति की बहन (सुमन की ननद)।<br>चरण 3: वही विनोद की पत्नी है → विनोद की पत्नी का भाई = सुमन का पति (विनोद का साला)।<br>वंश-वृक्ष:<br>सुमन का ससुर<br>↓<br>सुमन का पति = सुमन ↓&nbsp; पुत्री = विनोद<br>चरण 4: सुमन = विनोद के साले की पत्नी = सलहज।<br>अतः उत्तर = <b>सलहज</b><br><b>ध्यान दें:</b> साली = पत्नी की बहन; सुमन पत्नी की भाभी है, बहन नहीं।"},
    {"q":"Q, R की माँ है। S, R का पिता है। T, S की माँ है। T का Q से क्या संबंध है?","o":["माँ","ननद","सास","दादी"],"a":2,"e":"<b>हल:</b><br>चरण 1: Q, R की माँ; S, R का पिता → Q, S की पत्नी।<br>चरण 2: T, S की माँ।<br>वंश-वृक्ष:<br>T<br>↓<br>S = Q<br>↓<br>R<br>चरण 3: T = Q के पति (S) की माँ = सास।<br>अतः उत्तर = <b>सास</b><br><b>ध्यान दें:</b> दादी T, R की है, Q की नहीं।"},
    {"q":"A, B की बहन है। B, C की पत्नी है। C, D का पुत्र है। C का A से क्या संबंध है?","o":["साला","साढ़ू","जीजा (बहनोई)","देवर"],"a":2,"e":"<b>हल:</b><br>चरण 1: A, B की बहन (A स्त्री)।<br>चरण 2: B, C की पत्नी → C पुरुष।<br>चरण 3: C = A की बहन (B) का पति = जीजा (बहनोई)।<br>(D, C का पिता है — इस प्रश्न के लिए अनावश्यक सूचना।)<br>अतः उत्तर = <b>जीजा (बहनोई)</b><br><b>ध्यान दें:</b> साढ़ू = पत्नी की बहन का पति (पुरुष-पुरुष संबंध)।"},
    {"q":"एक दंपती के 3 पुत्र हैं और प्रत्येक पुत्र की केवल एक बहन है। इस परिवार में कुल कितने सदस्य हैं?","o":["9","6","5","8"],"a":1,"e":"<b>हल:</b><br>चरण 1: दंपती = 2 सदस्य।<br>चरण 2: 3 पुत्र हैं।<br>चरण 3: \"प्रत्येक पुत्र की केवल एक बहन\" → तीनों पुत्रों की बहन एक ही है → 1 पुत्री।<br>चरण 4: कुल = 2 + 3 + 1 = 6।<br>अतः उत्तर = <b>6</b><br><b>ध्यान दें:</b> हर पुत्र की अलग बहन मानने पर 8 आता है — यह गलत है।"},
    {"q":"मेरे दादा के इकलौते पुत्र की पत्नी की सास मेरी कौन है?","o":["बुआ","माँ","नानी","दादी"],"a":3,"e":"<b>हल:</b><br>चरण 1: मेरे दादा का इकलौता पुत्र = मेरे पिता।<br>चरण 2: पिता की पत्नी = मेरी माँ।<br>चरण 3: माँ की सास = पिता की माँ = दादी।<br>अतः उत्तर = <b>दादी</b>"},
    {"q":"एक पुरुष की ओर संकेत करते हुए नीना ने कहा, \"वह मेरे पिता की इकलौती बहन का इकलौता भाई है।\" वह पुरुष नीना का कौन है?","o":["पिता","चाचा","फूफा","मामा"],"a":0,"e":"<b>हल:</b><br>चरण 1: नीना के पिता की इकलौती बहन = नीना की बुआ।<br>चरण 2: बुआ का इकलौता भाई = नीना के पिता स्वयं (पिता भी बुआ के भाई हैं और भाई केवल एक है)।<br>अतः उत्तर = <b>पिता</b><br><b>ध्यान दें:</b> चाचा तब होता जब बुआ का कोई दूसरा भाई होता।"},
    {"q":"एक महिला ने एक बच्चे से कहा, \"तुम्हारे पिता की इकलौती बहन मेरी इकलौती ननद है, और मेरे पति का कोई भाई नहीं है।\" महिला उस बच्चे की कौन है?","o":["बुआ","चाची","माँ","मामी"],"a":2,"e":"<b>हल:</b><br>चरण 1: बच्चे के पिता की इकलौती बहन = बच्चे की बुआ।<br>चरण 2: वही बुआ महिला की इकलौती ननद है → बुआ, महिला के पति की बहन है।<br>चरण 3: अतः बच्चे के पिता और महिला के पति दोनों उस बुआ के भाई हैं।<br>चरण 4: महिला के पति का कोई भाई नहीं → दोनों अलग व्यक्ति नहीं हो सकते → बच्चे के पिता = महिला का पति।<br>चरण 5: अतः महिला = बच्चे की माँ।<br>अतः उत्तर = <b>माँ</b><br><b>ध्यान दें:</b> चाची तब होती जब पति का कोई भाई (बच्चे का पिता) होता — प्रश्न में यह नकारा गया है।"},
    {"q":"M, N की संतान है। N, O का भाई है। O, P की पत्नी है। M का O से क्या संबंध है?","o":["भांजा या भांजी (लिंग अज्ञात)","पोता","पुत्र","भतीजा या भतीजी (लिंग अज्ञात)"],"a":3,"e":"<b>हल:</b><br>चरण 1: M, N की संतान (लिंग अज्ञात)।<br>चरण 2: N, O का भाई → N पुरुष, O उसकी बहन (O, P की पत्नी है → O स्त्री)।<br>चरण 3: O = M के पिता (N) की बहन = बुआ।<br>वंश-वृक्ष:<br>N (पु.) — O (स्त्री) = P<br>↓<br>M (?)<br>चरण 4: बुआ के लिए भाई की संतान = भतीजा/भतीजी; M का लिंग अज्ञात।<br>अतः उत्तर = <b>भतीजा या भतीजी (लिंग अज्ञात)</b><br><b>ध्यान दें:</b> भांजा/भांजी तब होता जब M, O की बहन की संतान होता।"},
    {"q":"रोहित ने एक फ़ोटो दिखाकर कहा, \"यह मेरे पुत्र की इकलौती बुआ के पिता की तस्वीर है।\" फ़ोटो किसकी है?","o":["रोहित के पिता की","रोहित के ससुर की","स्वयं रोहित की","रोहित के दादा की"],"a":0,"e":"<b>हल:</b><br>चरण 1: रोहित के पुत्र की बुआ = पुत्र के पिता (रोहित) की बहन।<br>चरण 2: \"इकलौती बुआ\" = रोहित की इकलौती बहन।<br>चरण 3: बहन के पिता = रोहित के पिता।<br>अतः फ़ोटो = <b>रोहित के पिता की</b><br><b>ध्यान दें:</b> ससुर चुनना गलत है — बुआ पिता (रोहित) की बहन होती है, पत्नी की बहन नहीं।"}
  ]
});
